document.addEventListener("DOMContentLoaded", () => {
  const trigger = document.getElementById("chatButton");
  const overlay = document.getElementById("chatbotOverlay");
  const frame = document.getElementById("chatbotFrame");
  const invite = document.querySelector(".chat-invite");
  if (!trigger || !overlay || !frame) return;
  const CHATBOT_B64 = "";
  let loaded = false;
  const ensureLoaded = () => {
    if (loaded) return;
    try {
      const bin = atob(CHATBOT_B64);
      const bytes = new Uint8Array(bin.length);
      for (let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
      frame.srcdoc = new TextDecoder("utf-8").decode(bytes);
      loaded = true;
    } catch (err) {
      console.error("No se pudo cargar Tuky", err);
      frame.srcdoc = '<!doctype html><html><body style="font-family:Arial;padding:24px;color:#173764"><h2>Tuky</h2><p>No fue posible iniciar el asistente. Recarga la página e inténtalo nuevamente.</p></body></html>';
    }
  };
  const openChatbot = () => {
    ensureLoaded();
    overlay.classList.add("is-open");
    overlay.setAttribute("aria-hidden","false");
    document.body.classList.add("chatbot-is-open");
  };
  const closeChatbot = () => {
    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden","true");
    document.body.classList.remove("chatbot-is-open");
  };
  trigger.addEventListener("click", e => { e.preventDefault(); openChatbot(); });
  overlay.querySelectorAll("[data-chatbot-close]").forEach(el => el.addEventListener("click", closeChatbot));
  invite?.addEventListener("click", e => { if (!e.target.closest(".chat-invite__close")) openChatbot(); });
  window.addEventListener("message", e => { if (e.data?.type === "SEPRIGUA_CHATBOT_CLOSE") closeChatbot(); });
  document.addEventListener("keydown", e => { if (e.key === "Escape" && overlay.classList.contains("is-open")) closeChatbot(); });
});
